#include "NavegadorPresets.h"
PresetBrowser::PresetBrowser(VocaProcessor& p):processador(p){
 setLookAndFeel(&aparencia);for(auto* b:{&excluir,&renomear,&salvar})b->getProperties().set("acao",true);for(auto* b:{&fechar,&tags,&limpar,&favoritos,&tipo,&artista,&todos,&estrela})b->getProperties().set("semFundo",true);estrela.getProperties().set("estrela",true);fechar.getProperties().set("estrela",true);
 titulo.setText("MANLEY VOXBOX CS PRESETS",juce::dontSendNotification);titulo.setFont(juce::Font(11,juce::Font::bold));titulo.setJustificationType(juce::Justification::centred);
 for(auto* c:std::initializer_list<juce::Component*>{&titulo,&fechar,&busca,&tags,&limpar,&favoritos,&tipo,&artista,&todos,&rolagem,&nome,&estrela,&excluir,&renomear,&salvar,&lista,&aviso})addAndMakeVisible(c);
 busca.setColour(juce::TextEditor::backgroundColourId,juce::Colour(0xff111113));busca.setColour(juce::TextEditor::outlineColourId,juce::Colour(0xff3a3a3d));busca.onTextChange=[this]{atualizar();};busca.setTitle("Search presets");
 nome.setColour(juce::TextEditor::backgroundColourId,juce::Colours::transparentBlack);nome.setColour(juce::TextEditor::outlineColourId,juce::Colours::transparentBlack);nome.setJustification(juce::Justification::centred);nome.setFont(juce::Font(11,juce::Font::bold));nome.setTitle("Preset name");
 aviso.setFont(juce::Font(9));aviso.setColour(juce::Label::textColourId,juce::Colour(0xff96969d));
 rolagem.setViewedComponent(&grade,false);rolagem.setScrollBarsShown(true,false);rolagem.setScrollBarThickness(5);
 lista.setModel(this);lista.setRowHeight(32);lista.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xff19191c));lista.setColour(juce::ListBox::outlineColourId,juce::Colours::transparentBlack);
 fechar.onClick=[this]{if(auto* janela=findParentComponentOfClass<juce::DocumentWindow>())janela->setVisible(false);};
 limpar.onClick=[this]{filtros.clear();atualizar();};tags.onClick=[this]{mostrarTags=!mostrarTags;atualizar();};favoritos.onClick=[this]{somenteFavoritos=!somenteFavoritos;atualizar();};
 tipo.onClick=[this]{aba=0;atualizar();};artista.onClick=[this]{aba=1;atualizar();};todos.onClick=[this]{aba=2;atualizar();};
 estrela.onClick=[this]{processador.alternarFavorito(processador.getCurrentProgram());atualizar();};
 salvar.onClick=[this]{auto n=nome.getText();const auto& atual=processador.bank[(size_t)processador.getCurrentProgram()];if(!atual.isUser&&n==atual.name)n+=" (User)";auto categorias=atual.tags;for(auto& f:filtros)if(!f.containsChar(':'))categorias.addIfNotAlreadyThere(f);if(processador.salvarPreset(n,categorias)<0)aviso.setText(juce::String::fromUTF8("Nome vazio ou já existente."),juce::dontSendNotification);else{busca.clear();somenteFavoritos=false;atualizar();}};
 renomear.onClick=[this]{if(!processador.renomearPreset(processador.getCurrentProgram(),nome.getText()))aviso.setText(juce::String::fromUTF8("Nome vazio ou já existente."),juce::dontSendNotification);atualizar();};
 excluir.onClick=[this]{const int indice=processador.getCurrentProgram();const auto id=processador.bank[(size_t)indice].id;auto seguro=juce::Component::SafePointer<PresetBrowser>(this);juce::AlertWindow::showOkCancelBox(juce::MessageBoxIconType::QuestionIcon,"Excluir preset",processador.bank[(size_t)indice].name,"Excluir","Cancelar",this,juce::ModalCallbackFunction::create([seguro,id](int resposta){if(seguro&&resposta){for(size_t i=0;i<seguro->processador.bank.size();++i)if(seguro->processador.bank[i].id==id){seguro->processador.excluirPreset((int)i);break;}seguro->atualizar();}}));};
 setSize(385,480);atualizar();
}
void PresetBrowser::paint(juce::Graphics& g){g.setGradientFill(juce::ColourGradient(juce::Colour(0xff252528),0,0,juce::Colour(0xff1e1e20),0,(float)getHeight(),false));g.fillAll();g.setColour(juce::Colour(0xff2c2c30));g.fillRect(8,nome.getY(),getWidth()-16,excluir.getBottom()-nome.getY()+5);g.setColour(juce::Colour(0xff3a3a3d));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(.5f),3,1);auto* ativo=aba==0?&tipo:aba==1?&artista:&todos;if(mostrarTags){g.setColour(juce::Colours::white);auto r=ativo->getBounds();g.fillRect(r.getX(),r.getBottom()-2,r.getWidth(),2);}}
bool PresetBrowser::corresponde(const Preset& p)const{if(somenteFavoritos&&!p.favorite)return false;for(auto& f:filtros){if(f.startsWith("artist:")){if(p.artist!=f.substring(7))return false;}else if(f.startsWith("group:")){if(p.group!=f.substring(6))return false;}else if(!p.tags.contains(f))return false;}return (p.name+" "+p.group+" "+p.artist+" "+p.tags.joinIntoString(" ")).containsIgnoreCase(busca.getText());}
void PresetBrowser::desenharTags(){
 botoesTags.clear();chips.clear();juce::StringArray valores;
 if(aba!=1)valores={"Present","Light","Heavy","Saturated","Best Of","Vocal","Drums","Bright","Limiter","De-Ess","Dark","Bass"};
 for(auto& p:processador.bank){if(aba!=1)for(auto& t:p.tags)if(t!=p.group)valores.addIfNotAlreadyThere(t);if(aba!=0&&p.artist.isNotEmpty())valores.addIfNotAlreadyThere("artist:"+p.artist);if(aba==2&&p.group.isNotEmpty())valores.addIfNotAlreadyThere("group:"+p.group);}
 if(aba!=0)std::sort(valores.begin(),valores.end(),[](const juce::String& a,const juce::String& b){const auto nome=[](const juce::String& v){return v.containsChar(':')?v.fromFirstOccurrenceOf(":",false,false):v;};return nome(a).compareIgnoreCase(nome(b))<0;});
 auto criar=[this](const juce::String& valor,bool chip){auto b=std::make_unique<juce::TextButton>((valor.containsChar(':')?valor.fromFirstOccurrenceOf(":",false,false):valor)+(chip?juce::String::fromUTF8(" ×"):""));b->getProperties().set("chip",chip);b->onClick=[this,valor,chip]{if(chip)filtros.removeString(valor);else filtros.addIfNotAlreadyThere(valor);atualizar();};b->setColour(juce::TextButton::buttonColourId,juce::Colour(chip?0xff4a4a4f:0xff2a2a2d));if(chip)addAndMakeVisible(*b);else grade.addAndMakeVisible(*b);return b;};
 for(auto& f:filtros)chips.push_back(criar(f,true));for(auto& v:valores)if(!filtros.contains(v))botoesTags.push_back(criar(v,false));
}
void PresetBrowser::atualizar(){atualizando=true;linhas.clear();for(size_t i=0;i<processador.bank.size();++i)if(corresponde(processador.bank[i]))linhas.push_back((int)i);lista.updateContent();lista.deselectAllRows();const int atual=processador.getCurrentProgram();for(size_t i=0;i<linhas.size();++i)if(linhas[i]==atual)lista.selectRow((int)i);const auto& p=processador.bank[(size_t)atual];nome.setText(p.name,false);estrela.setButtonText(p.favorite?juce::String::fromUTF8("★"):juce::String::fromUTF8("☆"));favoritos.setButtonText(somenteFavoritos?juce::String::fromUTF8("FAVORITES ★"):juce::String::fromUTF8("FAVORITES ☆"));excluir.setEnabled(p.isUser);renomear.setEnabled(p.isUser);limpar.setVisible(!filtros.isEmpty());desenharTags();atualizando=false;resized();lista.repaint();repaint();}
void PresetBrowser::paintListBoxItem(int linha,juce::Graphics& g,int w,int h,bool selecionada){if(!juce::isPositiveAndBelow(linha,linhas.size()))return;const auto& p=processador.bank[(size_t)linhas[(size_t)linha]];if(selecionada){g.setColour(juce::Colour(0xff4a4a4f));g.fillAll();}g.setColour(juce::Colours::white);g.setFont(juce::Font(11,juce::Font::bold));g.drawText(p.name,12,0,w-40,h,juce::Justification::centredLeft);if(p.favorite)pintarEstrela(g,{w-17.f,h*.5f},7,true);}
void PresetBrowser::selectedRowsChanged(int linha){if(atualizando||!juce::isPositiveAndBelow(linha,linhas.size()))return;processador.setCurrentProgram(linhas[(size_t)linha]);atualizar();}
void PresetBrowser::resized(){
 const int largura=getWidth();titulo.setBounds(8,0,largura-16,30);fechar.setBounds(largura-30,3,24,24);busca.setBounds(8,30,largura-16,36);tags.setBounds(14,71,47,28);limpar.setBounds(62,71,24,28);favoritos.setBounds(largura-138,71,124,28);
 for(auto* b:{&tipo,&artista,&todos})b->setVisible(mostrarTags);rolagem.setVisible(mostrarTags);int y=99;
 if(mostrarTags){tipo.setBounds(14,y,119,29);artista.setBounds(133,y,119,29);todos.setBounds(252,y,119,29);y+=35;int x=14;for(auto& b:chips){const int w=juce::jmin(180,26+b->getButtonText().length()*6);if(x+w>largura-14){x=14;y+=31;}b->setBounds(x,y,w,25);b->setVisible(true);x+=w+6;}if(!chips.empty())y+=31;rolagem.setBounds(14,y,largura-28,130);grade.setSize(largura-34,juce::jmax(130,((int)botoesTags.size()+2)/3*34-6));for(size_t i=0;i<botoesTags.size();++i)botoesTags[i]->setBounds((int)(i%3)*119,(int)(i/3)*34,113,28);y+=137;}else for(auto& b:chips)b->setVisible(false);
 y=juce::jmin(y,getHeight()-113);nome.setBounds(8,y,largura-42,25);estrela.setBounds(largura-34,y,26,25);y+=30;excluir.setBounds(8,y,119,30);renomear.setBounds(132,y,119,30);salvar.setBounds(256,y,largura-264,30);y+=36;lista.setBounds(8,y,largura-16,juce::jmax(32,getHeight()-y-24));aviso.setBounds(8,getHeight()-22,largura-16,16);
}
